// Recognizing the files Blueprint Visual Scripting generates (docs/output-placement.md): a graph's
// generated code names its graph in its first line(s), and the languages' support files are
// `vgraph_runtime.*`. The Codebase Map shows a graph in place of its generated code.

// Matches the line every generator writes first, e.g. "// Generated by ... from demo.vgraph." (or
// Go's "// Code generated by ... from demo.vgraph. DO NOT EDIT."), in the language's comments.
const HEADER = /^(?:\/\/|#|--) (?:Code generated|Generated) by Blueprint Visual Scripting from (.+?)\.(?: DO NOT EDIT\.)?$/;
// Support code's header names no graph.
const SUPPORT_HEADER = /^(?:\/\/|#|--) (?:Code generated|Generated) by Blueprint Visual Scripting(?:[:.]| DO NOT EDIT)/;

// The graph a file was generated from, by its header: among its first lines, since some languages
// need a line before it (PHP's "<?php").
export function generatedFrom(text: string): string | undefined {
  for (const line of text.split(/\r?\n/, 4)) {
    const found = HEADER.exec(line)?.[1];
    if (found) return found;
  }
  return undefined;
}

// Whether a file is the generated code's support code (a language's runtime), not a graph's.
export function isGeneratedSupport(fileName: string, text: string): boolean {
  const base = fileName.replace(/\\/g, '/').split('/').pop() ?? '';
  if (/^vgraph_runtime\./.test(base)) return true;
  return text.split(/\r?\n/, 4).some((line) => SUPPORT_HEADER.test(line) && !HEADER.test(line));
}
